/**
 * Injected script to update the <spl-textarea>'s value
 */

(() => {
  try {
    const { text, editorId } = JSON.parse(
      document.currentScript?.dataset.params ?? "{}",
    );

    const editor = document.getElementById(
      editorId as string,
    ) as HTMLTextAreaElement | null;
    if (!editor) return;

    if (editor.value) {
      editor.value += "\n\n";
    } else {
      editor.value = "";
    }

    editor.value += text;
    editor.dispatchEvent(
      new CustomEvent("spl-change", {
        bubbles: true,
        detail: { value: editor.value },
      }),
    );
  } catch {}
})();
